package com.victorpena.just_in_transit;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static com.victorpena.just_in_transit.JourneyLogicTests.*;
import java.time.*;import org.junit.jupiter.api.Test;
class NotificationTests {
    @Test void onlyAllowsKnownHttpsPushHosts(){assertTrue(PushTransport.allowedEndpoint("https://web.push.apple.com/token"));assertTrue(PushTransport.allowedEndpoint("https://fcm.googleapis.com/wp/token"));assertFalse(PushTransport.allowedEndpoint("https://fcm.googleapis.com.attacker.invalid/x"));assertFalse(PushTransport.allowedEndpoint("http://fcm.googleapis.com/x"));assertFalse(PushTransport.allowedEndpoint("https://127.0.0.1/x"));assertFalse(PushTransport.allowedEndpoint("https://fcm.googleapis.com:8080/x"));assertFalse(PushTransport.allowedEndpoint("https://user@fcm.googleapis.com/x"));}
    @Test void scheduledReminderHasSourceAndIsNotRepeatedAfterBoarding(){var selected=selected();var watch=new CommuteNotifications.Watch("p",form(),selected,null,at("07:00"));var notices=CommuteNotifications.notices(watch,selected,null,LiveSnapshot.empty(),at("07:00"));assertTrue(notices.stream().anyMatch(x->x.key().equals("leave-soon") && x.body().contains("Scheduled")));var active=ActiveJourney.view(started(),schedule(),LiveSnapshot.empty(),at("07:05"));assertFalse(CommuteNotifications.notices(new CommuteNotifications.Watch("t",form(),selected,started(),at("07:04")),active.option(),active,LiveSnapshot.empty(),at("07:05")).stream().anyMatch(x->x.key().startsWith("leave")));}
    @Test void finishingStopsWatchAndUnavailableTransportDoesNotReadFeeds(){var watches=mock(TripWatchRepository.class);var subs=mock(PushSubscriptionRepository.class);var push=mock(PushTransport.class);var schedule=mock(ScheduleStore.class);var live=mock(RealtimeStore.class);var service=new CommuteNotifications(watches,subs,push,schedule,live,Clock.fixed(at("07:00"),ZoneOffset.UTC));service.update("owner",null);verify(watches).deleteById("owner");service.tick();verifyNoInteractions(schedule,live);}
    @Test void originalTimingSnapshotSurvivesProgress(){var s=started();assertEquals(at("07:15"),s.facts().predictions().get("ON_24"));var updated=ActiveJourney.advance(s,schedule(),LiveSnapshot.empty(),at("07:17"));assertEquals(at("07:15"),updated.facts().predictions().get("ON_24"));assertEquals(at("07:17"),updated.facts().confirmations().get("ON_24"));}

    @Test void canceledOrChangedWatchIsNotDelivered()throws Exception {
        var watches=mock(TripWatchRepository.class);var subs=mock(PushSubscriptionRepository.class);var push=mock(PushTransport.class);var schedule=mock(ScheduleStore.class);var live=mock(RealtimeStore.class);
        var record=new TripWatch();record.owner="owner";record.revision="old";record.expiresAt=at("09:00");record.payload=tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(new CommuteNotifications.Watch("p",form(),selected(),null,at("07:00")));
        when(push.available()).thenReturn(true);when(watches.findTop100ByOwnerGreaterThanOrderByOwnerAsc(anyString())).thenReturn(java.util.List.of(record));when(subs.findById("owner")).thenReturn(java.util.Optional.of(new PushSubscription()));when(schedule.get()).thenReturn(schedule());when(live.get()).thenReturn(RealtimeStore.Snapshot.empty());when(watches.existsByOwnerAndRevision("owner","old")).thenReturn(false);
        new CommuteNotifications(watches,subs,push,schedule,live,Clock.fixed(at("07:00"),ZoneOffset.UTC)).tick();verify(push,never()).send(any(),anyString(),anyString(),anyString());verify(watches,never()).save(any());
    }
}
